static int(*real_open_fn)(const char*,int,...);static int(*real_openat_fn)(int,const char*,int,...);
static int target(const char*p,int f){const char*t=getenv("FIFO_TARGET");char r[PATH_MAX];return t&&p&&!strcmp(p,t)&&(f&(O_WRONLY|O_RDWR))||(t&&p&&realpath(p,r)&&!strcmp(r,t)&&(f&(O_WRONLY|O_RDWR)));}
static void mark(void){const char*h=getenv("HOME");char p[4096];snprintf(p,sizeof p,"%s/open.pid",h);FILE*f=fopen(p,"w");if(f){fprintf(f,"%ld\n",(long)getpid());fclose(f);}}
int open(const char*p,int f,...){if(!real_open_fn)real_open_fn=dlsym(RTLD_NEXT,"open");mode_t m=0;if(f&O_CREAT){va_list a;va_start(a,f);m=va_arg(a,int);va_end(a);}if(target(p,f))mark();return real_open_fn(p,f,m);}
int open64(const char*p,int f,...){if(!real_open_fn)real_open_fn=dlsym(RTLD_NEXT,"open64");mode_t m=0;if(f&O_CREAT){va_list a;va_start(a,f);m=va_arg(a,int);va_end(a);}if(target(p,f))mark();return real_open_fn(p,f,m);}
int openat(int d,const char*p,int f,...){if(!real_openat_fn)real_openat_fn=dlsym(RTLD_NEXT,"openat");mode_t m=0;if(f&O_CREAT){va_list a;va_start(a,f);m=va_arg(a,int);va_end(a);}if(target(p,f))mark();return real_openat_fn(d,p,f,m);}

