#!/usr/bin/python3
import os,time
h=os.environ['HOME'];deadline=time.time()+10;pid=None
while time.time()<deadline:
 try:pid=int(open(h+'/open.pid').read().strip());break
 except (FileNotFoundError,ValueError):time.sleep(.01)
if pid is None:raise SystemExit(2)
w='/proc/%d/wchan'%pid;seen=False
while time.time()<deadline:
 try:
  s=open(w).read().strip()
  if s and s not in ('0','running'):seen=True;break
 except FileNotFoundError:break
 time.sleep(.01)
if not seen:raise SystemExit(3)
os.unlink(h+'/open.pid');open(h+'/open.ready','w').write(s+'\n')
